// mysql2 shape: a base method calls this.end() with no argument; the subclass redeclares end(callback)
// and forwards to super.end(callback).
class Conn {
  constructor(id) { this.id = id; this._closing = false; this.log = []; }
  shutdown() { if (!this._closing) { this.end(); } return this.log.join(","); }
  end(callback) { this._closing = true; this.log.push("conn:" + this.id); if (callback) callback(null); }
  query(sql, cb) { this.log.push("q:" + sql); this.end(cb); return this.log.length; }
}
class PoolConn extends Conn {
  end(callback) {
    this.log.push("pool-end:" + this.id + ":" + typeof callback);
    super.end(callback);
  }
}
module.exports = { Conn, PoolConn };
